option.value:
/* ========== THEME GLOBAL LIGHT ========== */

body {
  background-color: #f5f5f5; /* gris très clair */
  color: #333;
  font-family: "Arial", sans-serif;
  margin: 0;
  padding: 0;
}

/* Titres */
h1, h2 {
  font-weight: 500;
  color: #222;
}

/* Boutons génériques */
button {
  padding: 6px 10px;
  border-radius: 4px;
  border: 1px solid #ccc;
  background: white;
  cursor: pointer;
}

button:hover {
  background: #f0f0f0;
}

/* Zones (cartes) */
.card {
  background: white;
  padding: 20px;
  border-radius: 6px;
  box-shadow: 0px 2px 6px rgba(0,0,0,0.08);
  margin-bottom: 20px;
}

.header-pointage {
  position: sticky;
  top: 0;
  background: white;
  padding: 10px 0;
  z-index: 10;
  border-bottom: 1px solid #ddd;
}

.header-content {
  max-width: 900px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.main-header {
  position: sticky;
  top: 0;
  z-index: 20;
  background: white;
  border-bottom: 1px solid #ddd;
  padding: 10px 20px;

  display: flex;
  justify-content: space-between;
  align-items: center;
}

.nav-links a {
  margin-right: 20px;
  text-decoration: none;
  color: #333;
  font-weight: 500;
}

.nav-links a:hover {
  text-decoration: underline;
}

.app-version {
  margin-left: auto;
  font-size: 12px;
  color: #999;
  font-weight: normal;
}

.header-solde {
  min-width: 220px;
}

.montant-pill {
  display: inline-block;
  padding: 3px 8px;
  border-radius: 12px;
  font-weight: bold;
}

